export interface Session {
  readonly lastActivityAt: number;
}

export const SESSION_TIMEOUT_MS = 30 * 60 * 1_000;

export function isSessionExpired(session: Session, now: number): boolean {
  return now - session.lastActivityAt >= SESSION_TIMEOUT_MS;
}

export function remainingSessionMs(session: Session, now: number): number {
  const elapsed = now - session.lastActivityAt;
  return Math.max(0, SESSION_TIMEOUT_MS - elapsed);
}

const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // ADR-001: 30-minute session timeout

export interface Session {
  lastActivityAt: number;
}

/**
 * REQ-AUTH-002 (ADR-001): Sessions expire when 30 minutes have elapsed
 * since `lastActivityAt`. The boundary at exactly 30 minutes counts as
 * expired.
 */
export function isSessionExpired(session: Session, now: number): boolean {
  return now - session.lastActivityAt >= SESSION_TIMEOUT_MS;
}

/**
 * Returns the number of milliseconds remaining until the existing
 * 30-minute session timeout (see ADR-001 / REQ-AUTH-002), clamped to
 * zero once the session has expired.
 */
export function remainingSessionMs(session: Session, now: number): number {
  const remaining = session.lastActivityAt + SESSION_TIMEOUT_MS - now;
  return remaining > 0 ? remaining : 0;
}

export interface Session {
  readonly lastActivityAt: number;
}

export const SESSION_TIMEOUT_MS = 30 * 60 * 1_000;

export function isSessionExpired(session: Session, now: number): boolean {
  return now - session.lastActivityAt >= SESSION_TIMEOUT_MS;
}

export function remainingSessionMs(session: Session, now: number): number {
  const elapsed = now - session.lastActivityAt;
  const remaining = SESSION_TIMEOUT_MS - elapsed;
  return Math.max(0, remaining);
}
